css.value:
* {
    margin: 0;
    font-weight: var(--now-card-header_heading--title--font-weight, 600);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

* {
    margin: 0;
    font-size: var(--now-static-font-size--sm, 12px);
    display: -webkit-box;
    -webkit-line-clamp: 5;
    -webkit-box-orient: vertical;
    overflow: hidden;
    color: RGB(var(--now-color_text--secondary, 44, 50, 63));

}

* {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    font-weight: var(--now-card-header_heading--title--font-weight, 600);
    margin: 0;
    overflow: hidden;
}

* {
    display: -webkit-box;
    margin: 0;
    font-size: var(--now-static-font-size--md, 16px);
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    color: RGB(var(--now-color_text--secondary, 44, 50, 63));

}

script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	 return {
        elementId: api.state.layoutSelected == "grid"? "grid_card_repeater" : "list_card_repeater",
        restParams: [0 , api.state.layoutSelected == "grid"? "grid_card_container" : "list_card_container"],
    };
}
